"""Dedicated local page for labeled, full-resolution palm image collection."""

HTML = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>High-resolution palmprint capture</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:#17212b;font:16px system-ui,sans-serif}
header,main{max-width:1140px;margin:auto;padding:18px}header{display:flex;justify-content:space-between;align-items:center;gap:12px}
h1{font-size:1.5rem;margin:0}h2{font-size:1.1rem;margin:0 0 12px}a{color:#125e9c}
main{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(290px,1fr);gap:16px;padding-top:0}
.card{background:white;border:1px solid #dce2e8;border-radius:12px;padding:16px;box-shadow:0 2px 8px #0001}
.preview{background:#111;border-radius:8px;overflow:hidden;aspect-ratio:4/3;display:flex;align-items:center}
.preview img{width:100%;height:100%;object-fit:contain}.hint{color:#526270;font-size:.9rem;line-height:1.45}
label{display:block;font-weight:600;margin:12px 0 5px}input,select,textarea,button{font:inherit}
input,select,textarea{width:100%;padding:10px;border:1px solid #b9c4cc;border-radius:7px;background:white}
textarea{min-height:62px;resize:vertical}button{border:0;border-radius:8px;padding:11px 15px;background:#125e9c;color:white;cursor:pointer;margin-top:14px}
button:disabled{opacity:.55;cursor:wait}.row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.secondary{background:#687781;margin-left:8px}
#state{white-space:pre-wrap;border-radius:8px;padding:11px;background:#eaf1f7;margin-top:14px;min-height:44px}
.readiness{padding:12px;border-radius:8px;background:#eef3f7;margin-top:12px;font-weight:700}.readiness.ready{background:#dcf5e5;color:#176332}.readiness.wait{background:#fff1dd;color:#805000}
#progress{font-weight:700;margin-top:10px}.download{display:inline-block;margin-top:14px;padding:10px 14px;border-radius:8px;background:#176332;color:white;text-decoration:none}
#delete-current{background:#a52828}.danger{background:#a52828!important}.danger:hover{background:#861f1f!important}.session-list{display:grid;gap:8px}.session-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:11px 12px;border:1px solid #dce2e8;border-radius:8px;background:#f8fafb}.session-info{min-width:0}.session-title{font-weight:700}.session-meta{color:#526270;font-size:.88rem;line-height:1.4;overflow-wrap:anywhere}.session-row button{flex:0 0 auto;margin:0;padding:8px 11px}.empty-sessions{color:#526270}
#samples{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}#samples button{margin:0;background:#526b80;padding:7px 10px}#samples .sample-item{display:flex;gap:4px}#samples .sample-delete{background:#a52828}
#shot{display:block;width:auto;max-width:100%;max-height:430px;height:auto;border-radius:8px;cursor:crosshair;background:#111}#shot[hidden]{display:none}
#crop{width:100%;max-width:512px;height:auto;aspect-ratio:1;background:#e6ebef;image-rendering:pixelated;border-radius:8px}
.diagnostics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.diagnostics[hidden]{display:none}.diagnostics figure{margin:0}.diagnostics img{display:block;width:100%;max-width:512px;aspect-ratio:1;object-fit:contain;background:#e6ebef;border-radius:8px}.diagnostics figcaption{margin-top:5px;color:#526270;font-size:.9rem}
.wide{grid-column:1/-1}.links{display:flex;gap:18px;flex-wrap:wrap;margin:8px 0}
@media(max-width:800px){main{grid-template-columns:1fr}.wide{grid-column:1}}@media(max-width:520px){.diagnostics{grid-template-columns:1fr}}
</style></head><body>
<header><h1>High-resolution palmprint capture · Per session: 10 photos</h1><span><a href="/palmir">PalmIR Restoration comparison</a> · <a href="/">Back to capture</a></span></header>
<main><section class="card"><h2>Live preview · 480×360</h2><div class="preview"><img id="live" src="/frame.jpg" alt="Live feed"></div>
<div id="readiness" class="readiness">Start the session to take photos; there is no need to wait for a stability indicator.</div><div id="progress">No ten-photo session started yet.</div>
<p class="hint">The preview shows the same field of view as the full-resolution original. Position your hand and capture immediately. You need not move your hand or arm between shots. The original is saved even if palm localization fails. Inspect the crop and ridges afterward.</p></section>
<section class="card"><h2>Capture labels</h2>
<label for="subject">Subject ID</label><input id="subject" placeholder="e.g. p01" maxlength="40" pattern="[A-Za-z0-9_-]+" autocomplete="off">
<div class="row"><div><label for="hand">Hand</label><select id="hand"><option value="" selected>Select an option</option><option value="right">Right hand</option><option value="left">Left hand</option></select></div>
<div><label for="background">Background</label><select id="background"><option value="" selected>Select an option</option><option value="existing">Current background</option><option value="white">White paper</option><option value="other">Other</option></select></div></div>
<label for="distance">Lens-to-palm distance (cm, optional)</label><input id="distance" type="number" min="5" max="100" step="0.5" inputmode="decimal">
<label for="notes">Notes (optional)</label><textarea id="notes" maxlength="200" placeholder="Example: fixed mount, IR light, hand repositioned before capture"></textarea>
<button id="start">Start ten-photo session</button><button id="capture" disabled>Start session to capture</button><button id="abandon" class="secondary" hidden>Abandon session</button>
<a id="download" class="download" href="#" hidden>Download all ten photos ZIP</a><button id="delete-current" class="danger" hidden>Delete session photos</button><div id="state">Enter the labels and start a session first.</div>
<p class="hint">Keep the hand, background, distance and lighting constant throughout the session. Each shot saves the full-resolution original, preceding preview frame, exposure and gain.</p></section>
<section class="card wide"><h2>Review captures · Session photos</h2><div id="samples"></div><p id="summary" class="hint">No photos yet.</p><button id="delete-sample" class="danger" hidden>Delete this photo</button>
<div id="diagnostics" class="diagnostics" hidden><figure><img id="roi-image" alt="Palm crop localized from the full-resolution original"><figcaption>128×128 Palm crop: localized again from the full-resolution original. Check fingers, background and alignment. Live verification still uses preview frames.</figcaption></figure><figure><img id="detail-image" alt="Palm 512×512 Original pixel detail"><figcaption>512×512 Original detail: inspect ridges, reflections and focus.</figcaption></figure></div>
<div class="links"><a id="roi-link" href="#" hidden target="_blank">Enlarge palm crop</a><a id="detail-link" href="#" hidden target="_blank">Enlarge original detail</a><a id="full-link" href="#" hidden target="_blank">Open full original</a><a id="meta-link" href="#" hidden target="_blank">View capture settings</a></div>
<p class="hint">Full-resolution preview: click the palm to see nearby pixels at their original resolution below.</p><img id="shot" alt="Recent full-resolution photos" hidden>
  <canvas id="crop" width="512" height="512"></canvas></section>
<section class="card wide"><h2>Saved palmprint sessions</h2><p class="hint">Each row represents a session folder organized by subject ID and hand. Deleting removes only its originals, ROI, metadata, session manifest and corresponding ZIP contents.</p><div id="session-list" class="session-list"><div class="empty-sessions">Loading saved sessions…</div></div></section></main>
<script>
const live=document.getElementById('live'),shot=document.getElementById('shot'),crop=document.getElementById('crop');
const state=document.getElementById('state'),capture=document.getElementById('capture'),start=document.getElementById('start'),abandon=document.getElementById('abandon'),deleteCurrent=document.getElementById('delete-current');
const readiness=document.getElementById('readiness'),progress=document.getElementById('progress'),download=document.getElementById('download');
const deleteSample=document.getElementById('delete-sample');
const formIds=['subject','hand','background','distance','notes'];let lastPreview=null,busy=false,activeSession=null,sampleSignature='',activeSampleIds=[],selectedSample=null;
async function refreshPreview(){try{const r=await fetch('/frame.jpg?t='+Date.now(),{cache:'no-store'});if(r.ok){const next=URL.createObjectURL(await r.blob());live.onload=()=>{if(lastPreview)URL.revokeObjectURL(lastPreview);lastPreview=next};live.src=next}}catch(e){}setTimeout(refreshPreview,250)}
refreshPreview();
function syncDeleteSample(){const index=activeSampleIds.indexOf(selectedSample);deleteSample.hidden=!activeSession||index<0;deleteSample.disabled=busy;deleteSample.textContent=index<0?'Delete this photo':`Delete photo ${index+1}`}
function clearSample(){selectedSample=null;shot.hidden=true;document.getElementById('diagnostics').hidden=true;document.getElementById('summary').textContent='Select a photo to inspect.';for(const id of ['full-link','roi-link','detail-link','meta-link'])document.getElementById(id).hidden=true;syncDeleteSample()}
function showSample(d){if(!d||!d.sample_id)return;selectedSample=d.sample_id;syncDeleteSample();const base='/api/collection/sample/'+encodeURIComponent(d.sample_id);
shot.src=base+'/full.jpg?t='+Date.now();shot.hidden=false;
const full=document.getElementById('full-link'),meta=document.getElementById('meta-link');full.href=base+'/full.jpg';meta.href=base+'/metadata.json';full.hidden=false;meta.hidden=false;
const diagnostics=document.getElementById('diagnostics'),roiLink=document.getElementById('roi-link'),detailLink=document.getElementById('detail-link');diagnostics.hidden=!d.roi_available;roiLink.hidden=!d.roi_available;detailLink.hidden=!d.roi_available;
if(d.roi_available){roiLink.href=base+'/roi_128.png';detailLink.href=base+'/palm_detail_512.jpg';document.getElementById('roi-image').src=roiLink.href+'?t='+Date.now();document.getElementById('detail-image').src=detailLink.href+'?t='+Date.now()}
const exposure=d.exposure_ms==null?'':(' · Exposure '+Number(d.exposure_ms).toFixed(1)+' ms');const gain=d.analogue_gain==null?'':(' · Gain '+Number(d.analogue_gain).toFixed(2));
document.getElementById('summary').textContent=d.sample_id+' · '+d.width+'×'+d.height+' · '+d.subject+' / '+d.hand+' · '+d.background+exposure+gain;
}
function showDamagedSample(id,index){clearSample();selectedSample=id;syncDeleteSample();document.getElementById('summary').textContent=`Photo ${index+1} has missing or corrupt capture settings. The original may be unavailable; delete it and retake.`;state.textContent='The photo was not fully saved. Delete it and retake.'}
function renderSamples(ids){activeSampleIds=ids.slice();syncDeleteSample();const signature=ids.join(',');if(signature===sampleSignature)return;sampleSignature=signature;const list=document.getElementById('samples');list.replaceChildren();ids.forEach((id,index)=>{const group=document.createElement('div');group.className='sample-item';const button=document.createElement('button');button.textContent=`View photo ${index+1}`;button.onclick=async()=>{try{const r=await fetch('/api/collection/sample/'+encodeURIComponent(id)+'/metadata.json',{cache:'no-store'});if(r.status===404){showDamagedSample(id,index);return}if(!r.ok)throw Error('Cannot load photo');const raw=await r.text();let data;try{data=JSON.parse(raw)}catch(e){showDamagedSample(id,index);return}if(!data||data.sample_id!==id){showDamagedSample(id,index);return}showSample(data)}catch(e){state.textContent=e.message}};const remove=document.createElement('button');remove.className='sample-delete';remove.textContent=`Delete photo ${index+1}`;remove.onclick=()=>removeSample(id);group.append(button,remove);list.append(group)})}
function handLabel(hand){return hand==='left'?'Left hand':hand==='right'?'Right hand':hand||'Unknown hand'}
async function refreshSessions(){const list=document.getElementById('session-list');try{const r=await fetch('/api/collection/sessions?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Cannot load session');const d=await r.json(),sessions=d.sessions||[];list.replaceChildren();if(!sessions.length){const empty=document.createElement('div');empty.className='empty-sessions';empty.textContent='No saved sessions yet.';list.append(empty);return}for(const session of sessions){const row=document.createElement('div');row.className='session-row';const info=document.createElement('div');info.className='session-info';const title=document.createElement('div');title.className='session-title';title.textContent=`${session.subject||'Unnamed'} · ${handLabel(session.hand)}`;const meta=document.createElement('div');meta.className='session-meta';meta.textContent=`${session.sample_count}/${session.total} photos · ${session.background||'Unknown background'} · ${session.session_id}`;info.append(title,meta);const actions=document.createElement('div');if(session.phase==='complete'){const link=document.createElement('a');link.className='download';link.href='/api/collection/session/'+encodeURIComponent(session.session_id)+'.zip';link.textContent='Download ZIP';link.target='_blank';actions.append(link)}const remove=document.createElement('button');remove.className='danger';remove.textContent='Delete folder';remove.onclick=()=>deleteSession(session);actions.append(remove);row.append(info,actions);list.append(row)}}catch(e){list.textContent=e.message}}
async function deleteSession(session){const label=`${session.subject||'Unnamed'} · ${handLabel(session.hand)} · ${session.sample_count}/${session.total} photos`;if(!confirm(`Delete capture folder?\n${label}\n\nThese photos and records will move to a recoverable location.`))return;busy=true;deleteCurrent.disabled=true;try{const r=await fetch('/api/collection/delete-session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session.session_id})});const d=await r.json();if(!r.ok)throw Error(d.message||'Deletion failed');if(activeSession===session.session_id){activeSession=null;sampleSignature='';renderSamples([]);clearSample()}state.textContent=`Deleted ${d.deleted_samples} photos.`;await refreshState();await refreshSessions()}catch(e){state.textContent='Deletion failed: '+e.message}finally{busy=false;deleteCurrent.disabled=false}}
fetch('/api/collection/latest').then(r=>r.ok?r.json():null).then(showSample).catch(()=>{});
function lockForm(locked){for(const id of formIds)document.getElementById(id).disabled=locked}
async function refreshState(){try{const r=await fetch('/api/status?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('Status unavailable');const d=await r.json(),b=d.highres_batch||{phase:'idle',captured:0,total:10};
if(b.session_id&&activeSession!==b.session_id){activeSession=b.session_id;for(const id of ['subject','hand','background'])document.getElementById(id).value=b[id]||'';document.getElementById('distance').value=b.distance_cm==null?'':b.distance_cm;document.getElementById('notes').value=b.notes||'';if(!(b.sample_ids||[]).length){shot.hidden=true;document.getElementById('diagnostics').hidden=true;document.getElementById('summary').textContent='No session photos yet.';for(const id of ['full-link','roi-link','detail-link','meta-link'])document.getElementById(id).hidden=true}}
const phase=b.phase||'idle',tracking=d.roi_status==='tracking';
renderSamples(b.sample_ids||[]);
lockForm(phase==='await_hand');start.disabled=busy||(phase!=='idle'&&phase!=='complete');start.textContent=phase==='complete'?'Start a new ten-photo session':'Start ten-photo session';
abandon.hidden=phase!=='await_hand';abandon.disabled=busy;
capture.disabled=busy||!b.can_capture;capture.textContent=b.can_capture?`Capture photo ${b.next_sample}/10 · 3280×2464`:'Start session to capture';
 download.hidden=phase!=='complete';if(phase==='complete')download.href='/api/collection/session/'+encodeURIComponent(b.session_id)+'.zip';deleteCurrent.hidden=!b.session_id||!b.captured;deleteCurrent.disabled=busy;
progress.textContent=phase==='idle'?'No ten-photo session started yet.':`Session photos: ${b.captured}/10 photos`;
readiness.className='readiness';
if(phase==='idle'){readiness.textContent='Enter the labels and click Start ten-photo session.'}
else if(phase==='complete'){readiness.textContent='Ten photos complete. Download the session.';readiness.classList.add('ready')}
else if(b.can_capture&&tracking){readiness.textContent=`Palm detected. Capture photo ${b.next_sample} without removing your hand.`;readiness.classList.add('ready')}
else if(b.can_capture){readiness.textContent=`Capture photo ${b.next_sample} now. Palm not localized; the original will be saved but may have no automatic crop.`;readiness.classList.add('wait')}
}catch(e){capture.disabled=true;readiness.textContent='Camera status unavailable. Try again shortly.';readiness.className='readiness wait'}}
refreshState();setInterval(refreshState,400);refreshSessions();setInterval(refreshSessions,3000);
start.onclick=async()=>{const subject=document.getElementById('subject').value.trim(),hand=document.getElementById('hand').value,background=document.getElementById('background').value;
if(!/^[A-Za-z0-9_-]{1,40}$/.test(subject)){state.textContent='Use letters, digits, _ or - in the subject ID.';return}if(!hand||!background){state.textContent='Select the hand and background first.';return}
busy=true;start.disabled=true;try{const r=await fetch('/api/collection/start-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subject,hand,background,distance_cm:document.getElementById('distance').value,notes:document.getElementById('notes').value,client_time:new Date().toISOString()})});const d=await r.json();if(!r.ok)throw Error(d.message||'Could not start');state.textContent='Session started. Position your palm and capture photo 1 photos.'}catch(e){state.textContent='Could not start: '+e.message}finally{busy=false;await refreshState()}};
capture.onclick=async()=>{busy=true;capture.disabled=true;state.textContent='Capturing the full-resolution original. Keep your hand in view…';try{const r=await fetch('/api/collection/capture-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_time:new Date().toISOString()})});const d=await r.json();if(!r.ok)throw Error(d.message||'Capture failed');showSample(d);state.textContent=d.phase==='complete'?'Photo 10 saved. Download the session.':`Photo ${d.sample_index} saved. Keep the hand in view for the next photo.`;if(!d.roi_available)state.textContent+=' No palm crop was generated. The original was saved; check hand placement.'}catch(e){state.textContent='Capture failed: '+e.message}finally{busy=false;await refreshState()}};
abandon.onclick=async()=>{if(!confirm('Abandon this session? Captured photos will remain on the Pi. A new ten-photo session starts from the beginning.'))return;busy=true;abandon.disabled=true;try{const r=await fetch('/api/collection/abandon-batch',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.message||'Could not abandon session');activeSession=null;renderSamples([]);shot.hidden=true;document.getElementById('diagnostics').hidden=true;document.getElementById('summary').textContent='No session photos yet.';for(const id of ['full-link','roi-link','detail-link','meta-link'])document.getElementById(id).hidden=true;state.textContent='Session abandoned. Check the labels before starting another.'}catch(e){state.textContent='Could not abandon session: '+e.message}finally{busy=false;await refreshState()}};
deleteCurrent.onclick=async()=>{if(!activeSession)return;const sessions=await fetch('/api/collection/sessions?t='+Date.now(),{cache:'no-store'}).then(r=>r.json()).catch(()=>({sessions:[]}));const session=(sessions.sessions||[]).find(item=>item.session_id===activeSession);if(session)await deleteSession(session)};
async function removeSample(id){const session=activeSession,index=activeSampleIds.indexOf(id);if(!session||index<0||busy)return;if(!confirm(`Delete photo ${index+1}?\n\nThis photo will move to a recoverable location on the Pi; other photos remain. You can take a replacement.`))return;busy=true;syncDeleteSample();try{const r=await fetch('/api/collection/delete-sample',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session_id:session,sample_id:id})});const text=await r.text();let d;try{d=JSON.parse(text)}catch(e){throw Error('The device returned an incomplete result. Refresh and check whether the photo was deleted.')}if(!r.ok)throw Error(d.message||'Deletion failed');clearSample();state.textContent=`Deleted photo ${index+1}. Remaining: ${d.captured} photos. You can take replacements.`;await refreshState();await refreshSessions()}catch(e){state.textContent='Deletion failed: '+e.message}finally{busy=false;syncDeleteSample()}}
deleteSample.onclick=()=>removeSample(selectedSample);
shot.onclick=e=>{if(!shot.naturalWidth)return;const box=shot.getBoundingClientRect();const x=(e.clientX-box.left)/box.width*shot.naturalWidth,y=(e.clientY-box.top)/box.height*shot.naturalHeight;
const size=Math.min(512,shot.naturalWidth,shot.naturalHeight),sx=Math.max(0,Math.min(shot.naturalWidth-size,x-size/2)),sy=Math.max(0,Math.min(shot.naturalHeight-size,y-size/2));
const ctx=crop.getContext('2d');ctx.clearRect(0,0,512,512);ctx.imageSmoothingEnabled=false;ctx.drawImage(shot,sx,sy,size,size,0,0,512,512)};
</script></body></html>"""
